/* Tradex help · glossary — short names, abbreviations and business terms used in the ERP workspace and vendor portal.
   Entries with `ab` are underlined on screen at their first mention in each card/panel (see TX.help in tradex.js).
   Definitions follow the blueprint glossary (docs BP §33) and stock definitions (BP §9.2); sample values shown on
   screens (prices, day counts, limits, provider names) are examples, not rules. */
TX.help.add({
  /* ---------------------------------------------------------------- abbreviations */
  "g.atp": { t: "ATP", full: "Available to promise", ab: ["ATP"],
    short: "How many units can still be promised to new orders right now.",
    what: "ATP = sellable stock on hand − units already reserved for orders − the safety buffer (never below zero). Stock in quarantine, damaged, under repair or in transit is not sellable, so it is never counted.",
    why: "The website, branches and dealers all sell from this one number, so the same unit is never sold twice.",
    notes: ["Purchase orders and unconfirmed supplier stock do not add to ATP until the goods are received and accepted.", "A reservation lowers ATP immediately; dispatch then lowers physical stock."],
    rel: ["g.reservation", "g.safety-buffer", "g.quarantine"] },
  "g.awb": { t: "AWB", full: "Air waybill · courier tracking number", ab: ["AWB", "AWBs"],
    short: "The courier's tracking number for one parcel.",
    what: "The number the courier gives a parcel when a shipment is booked. It is printed on the shipping label and used to track the parcel.",
    why: "Tradex stores the AWB against each parcel so staff and customers can follow delivery, returns and pickups.",
    rel: ["g.manifest", "g.rto"] },
  "g.api": { t: "API", full: "Application programming interface", ab: ["API", "APIs"],
    short: "A direct system-to-system connection (no files or manual typing).",
    what: "A way for two systems to exchange data automatically — for example a supplier's system sending stock levels, or a courier confirming a booking.",
    why: "Connections by API are faster and less error-prone than spreadsheets; when one fails, the item appears as an exception for a person to check." },
  "g.asn": { t: "ASN", full: "Advance shipping notice", ab: ["ASN", "ASNs"],
    short: "A supplier's notice listing what is being shipped, before it arrives.",
    what: "A message from the supplier that lists the items, quantities and (for serialised goods) serial numbers in a shipment against a purchase order.",
    why: "The warehouse can prepare for receiving and check the delivery against the notice and the purchase order.",
    rel: ["g.po", "g.grn"] },
  "g.b2b": { t: "B2B", full: "Business-to-business · approved dealers", ab: ["B2B"],
    short: "Sales to approved business buyers (dealers) on business terms.",
    what: "In Tradex, B2B means approved dealers: businesses that buy with their own price list, quantity pricing, quotes and, if approved, credit terms.",
    rel: ["g.b2c", "g.price-list", "g.credit-limit"] },
  "g.b2c": { t: "B2C", full: "Business-to-consumer", ab: ["B2C"],
    short: "Sales to ordinary consumers at public prices.",
    what: "Orders from individual customers on the website, in a branch, on WhatsApp or placed by staff for them." , rel: ["g.b2b"] },
  "g.bsp": { t: "BSP", full: "WhatsApp Business Solution Provider", ab: ["BSP"],
    short: "A Meta-approved company that connects a business to the WhatsApp Business Platform.",
    what: "Tradex can use WhatsApp through a BSP or directly through Meta's Cloud API. The choice of provider is still open.",
    rel: ["g.channel"] },
  "g.cod": { t: "COD", full: "Cash on delivery", ab: ["COD"],
    short: "The customer pays the courier when the parcel is delivered.",
    what: "The courier collects the money and later sends it to Tradex. COD orders have more refused deliveries, so they are watched in reports and reconciled against courier remittances.",
    rel: ["g.rto", "g.reconciliation"] },
  "g.gst-parts": { t: "CGST · SGST · IGST", full: "Central, State and Integrated GST", ab: ["CGST", "SGST", "IGST"],
    short: "The parts GST is split into on an invoice.",
    what: "For a sale inside the same state, GST is split equally into CGST (central) and SGST (state). For a sale to another state, the whole amount is IGST (integrated).",
    why: "Invoices, credit notes and GST reports show these parts separately.", rel: ["g.gst", "g.gstin", "g.hsn"] },
  "g.cn": { t: "CN", full: "Credit note", ab: ["CN"],
    short: "A document that reduces or cancels an invoice amount (for example after a refund).",
    what: "When money is returned for an invoiced sale — a return, a cancellation after invoicing, a price correction — a credit note is issued so the tax records stay correct. Suppliers also issue credit notes to Tradex.",
    rel: ["g.debit-note", "g.refund"] },
  "g.csv": { t: "CSV / XLSX", full: "Spreadsheet file formats", ab: ["CSV", "XLSX"],
    short: "Spreadsheet files used for imports and exports.",
    what: "CSV is a plain text table; XLSX is an Excel workbook. Tradex uses them for bulk catalog imports, supplier feeds and report exports. Imports are validated first; rows with errors are shown for correction, never loaded silently." },
  "g.doa": { t: "DOA", full: "Dead on arrival", ab: ["DOA"],
    short: "An item that does not work when first received.",
    what: "A unit that is faulty from the start — when the customer receives it, or when Tradex receives it from a supplier. DOA cases usually get a replacement first, under the DOA policy or the supplier's DOA terms.",
    rel: ["g.rma", "g.rtv"] },
  "g.ean": { t: "EAN", full: "European Article Number · retail barcode", ab: ["EAN", "UPC"],
    short: "The number under a product's retail barcode.",
    what: "A standard barcode number printed on packaging. Tradex uses it, with the manufacturer part number, to match imported or supplier products to the right catalog item.",
    rel: ["g.mpn", "g.sku"] },
  "g.emi": { t: "EMI", full: "Equated monthly instalment", ab: ["EMI"],
    short: "Paying for a purchase in fixed monthly instalments.",
    what: "A payment option offered through the payment provider or the customer's bank. Tradex receives the full amount from the provider; the customer repays the lender." },
  "g.epr": { t: "EPR", full: "Extended producer responsibility (e-waste)", ab: ["EPR", "CPCB"],
    short: "E-waste registration that some sellers of electronics must hold.",
    what: "Under India's e-waste rules, producers and importers of electronics need an EPR authorisation from the CPCB (Central Pollution Control Board). Tradex records it for vendors where it applies and warns before it expires.",
    rel: ["g.kyc"] },
  "g.erp": { t: "ERP", full: "Enterprise resource planning", ab: ["ERP"],
    short: "The staff system that runs stock, orders, purchasing and operations.",
    what: "The ERP workspace is where Tradex staff manage orders, stock, purchasing, returns, pricing, suppliers and reports. Customers use the storefront; suppliers use the vendor portal." },
  "g.eta": { t: "ETA", full: "Estimated time of arrival", ab: ["ETA"], short: "When a parcel, transfer or delivery is expected to arrive." },
  "g.fy": { t: "FY", full: "Financial year (April – March)", ab: ["FY"],
    short: "India's financial year, 1 April to 31 March.",
    what: "FY 2026-27 runs from 1 April 2026 to 31 March 2027. Invoice and credit-note numbering usually restarts each financial year." },
  "g.grn": { t: "GRN", full: "Goods receipt note", ab: ["GRN", "GRNs"],
    short: "The record that goods from a supplier were physically received.",
    what: "Created when a delivery is counted and scanned in against a purchase order. It records what arrived, the quantities, serial numbers and any shortages or damage.",
    why: "Received goods first go to inspection (QC). Only accepted units become sellable. The supplier's invoice is checked against the PO and GRN before payment.",
    rel: ["g.po", "g.qc", "g.three-way"] },
  "g.gst": { t: "GST", full: "Goods and Services Tax", ab: ["GST"],
    short: "India's tax on sales of goods and services.",
    what: "GST is added to the taxable value of a sale. Prices may be shown including GST (\"incl. GST\") or excluding it (\"ex-GST\"). Which convention each buyer type sees is still to be confirmed by finance.",
    rel: ["g.gst-parts", "g.gstin", "g.hsn"] },
  "g.gstin": { t: "GSTIN", full: "GST identification number", ab: ["GSTIN", "GSTINs"],
    short: "A business's 15-character GST registration number.",
    what: "Every GST-registered business has a GSTIN. It is printed on invoices, checked when dealers and vendors apply, and needed for business buyers to claim input tax credit.",
    rel: ["g.gst", "g.kyc"] },
  "g.hsn": { t: "HSN", full: "Harmonised System of Nomenclature code", ab: ["HSN"],
    short: "The product classification code that decides the GST rate.",
    what: "Each product type has an HSN code. It appears on invoices and determines which GST rate applies, so every catalog product needs a correct one before it can be sold.",
    rel: ["g.gst"] },
  "g.ifsc": { t: "IFSC", full: "Indian Financial System Code", ab: ["IFSC"],
    short: "The code that identifies a bank branch for transfers.",
    what: "Used with an account number for NEFT, RTGS and IMPS transfers. Bank details of vendors and dealers are verified before any payout or refund to them." },
  "g.irn": { t: "IRN", full: "Invoice reference number (e-invoice)", ab: ["IRN"],
    short: "The unique number the government e-invoice portal gives an invoice.",
    what: "For businesses that must issue e-invoices, each invoice is registered with the government portal and receives an IRN and QR code. Whether and when this applies to Tradex is to be confirmed by finance." },
  "g.kyc": { t: "KYC", full: "Know your customer", ab: ["KYC"],
    short: "Identity and business documents checked before approving a partner.",
    what: "Documents such as GST registration, PAN, company registration and bank proof, collected when approving dealers and vendors. Viewing them is restricted by role and every view is logged.",
    rel: ["g.gstin", "g.pan", "g.audit"] },
  "g.mfa": { t: "MFA", full: "Multi-factor authentication", ab: ["MFA", "2FA"],
    short: "Signing in with a second proof, such as a code from an app.",
    what: "Besides the password, the user confirms sign-in with a one-time code or authenticator app. Required for privileged staff; which other users need it is still to be decided." },
  "g.moq": { t: "MOQ", full: "Minimum order quantity", ab: ["MOQ"],
    short: "The smallest quantity a supplier will sell in one order.",
    what: "Purchase suggestions are rounded up to the supplier's pack size or MOQ." , rel: ["g.rop"] },
  "g.mpn": { t: "MPN", full: "Manufacturer part number", ab: ["MPN"],
    short: "The maker's own model/part code for a product.",
    what: "Used with EAN barcodes to identify exactly which product a supplier or import row refers to, and to stop duplicate catalog items.", rel: ["g.ean", "g.sku"] },
  "g.neft": { t: "NEFT / RTGS / IMPS", full: "Indian bank transfer methods", ab: ["NEFT", "RTGS", "IMPS"],
    short: "Ways of sending money directly between bank accounts in India.",
    what: "Dealers may pay by bank transfer, and refunds or payouts to businesses are often sent this way. Each transfer has a UTR reference used to match it in reconciliation.", rel: ["g.utr", "g.reconciliation"] },
  "g.otp": { t: "OTP", full: "One-time password", ab: ["OTP", "OTPs"],
    short: "A short code sent by SMS, e-mail or WhatsApp to confirm an action.",
    what: "Used for sign-in, confirming a phone number, and — if enabled — handing over high-value deliveries." },
  "g.pan": { t: "PAN", full: "Permanent account number", ab: ["PAN"],
    short: "India's income-tax ID for a person or business.", what: "Collected from dealers and vendors during approval, together with GSTIN and bank details.", rel: ["g.kyc"] },
  "g.cin": { t: "CIN / Udyam", full: "Company registration numbers", ab: ["CIN", "MSME"],
    short: "Company (CIN) and small-business (Udyam/MSME) registration numbers.",
    what: "CIN identifies a registered company; Udyam registration identifies an MSME (micro, small or medium enterprise). Both are checked when approving vendors.", rel: ["g.kyc"] },
  "g.po": { t: "PO", full: "Purchase order", ab: ["PO", "POs"],
    short: "Tradex's formal order to a supplier: what, how many, at what price, by when.",
    what: "Created by purchasing (often from a reorder suggestion) and approved before sending. A PO does not change stock by itself — stock increases only when goods are received (GRN) and accepted.",
    rel: ["g.grn", "g.three-way", "g.rop"] },
  "g.pos": { t: "POS", full: "Point of sale · branch billing", ab: ["POS"],
    short: "The till/billing system used for sales in a branch.",
    what: "Branch sales are one of the sales channels. They draw from the same stock as the website, so a branch sale immediately reduces what the website can sell.", rel: ["g.channel"] },
  "g.qc": { t: "QC", full: "Quality check / inspection", ab: ["QC"],
    short: "Inspecting goods before they can be sold.",
    what: "New deliveries (inbound QC) and customer returns are inspected: serial numbers, condition, accessories, function tests. Units wait in quarantine until QC records a result.",
    rel: ["g.quarantine", "g.grn", "g.condition"] },
  "g.rma": { t: "RMA", full: "Return merchandise authorisation", ab: ["RMA", "RMAs"],
    short: "A return or warranty case — the request, its approval and everything that follows.",
    what: "Each customer return, replacement, warranty or DOA request gets an RMA number (for example RMA-0094). The RMA follows the item from the request, through pickup, receipt and inspection, to the refund and to what happens to the unit.",
    why: "It keeps every return traceable to the original order, serial number and the policy that applied at the time of sale.",
    read: "The \"RMA queue\" is simply the list of open return and warranty cases waiting for someone to act.",
    rel: ["g.quarantine", "g.disposition", "g.rtv", "g.doa"] },
  "g.rop": { t: "ROP", full: "Reorder point", ab: ["ROP"],
    short: "The stock level at which you should order more.",
    what: "When available stock falls to or below the reorder point, the item appears in purchase suggestions. It is usually based on sales per day × supplier lead time + a safety margin.",
    rel: ["g.lead-time", "g.po", "g.moq"] },
  "g.rto": { t: "RTO", full: "Return to origin (courier)", ab: ["RTO"],
    short: "A parcel the courier could not deliver and is sending back.",
    what: "If delivery fails (customer not available, refused, wrong address) the courier returns the parcel to Tradex. RTO parcels are received into quarantine and checked before the stock is sellable again.",
    notes: ["In backup and recovery planning, RTO can also mean \"recovery time objective\" — the target time to restore service."],
    rel: ["g.awb", "g.cod", "g.quarantine"] },
  "g.rtv": { t: "RTV", full: "Return to vendor", ab: ["RTV"],
    short: "Sending goods back to the supplier (supplier RMA).",
    what: "Faulty, DOA or wrongly supplied units are returned under the supplier's warranty or DOA terms, for a replacement or a credit note.", rel: ["g.rma", "g.cn"] },
  "g.sku": { t: "SKU", full: "Stock keeping unit", ab: ["SKU", "SKUs"],
    short: "One sellable version of a product (specification + condition).",
    what: "Each combination that is priced and stocked separately has its own SKU — for example the same laptop model new and as refurbished Grade A are two SKUs.",
    rel: ["g.serial", "g.condition"] },
  "g.sla": { t: "SLA", full: "Service level agreement · target time", ab: ["SLA", "SLAs"],
    short: "The time by which something should be done.",
    what: "A target such as \"dispatch by 16:00\" or \"refund decision within 6 hours\". Screens show the time left and turn amber or red as the deadline approaches or passes. The actual targets are set by the business.",
    read: "Green = on time · amber = due soon · red = overdue." },
  "g.tds": { t: "TDS", full: "Tax deducted at source", ab: ["TDS"],
    short: "Income tax the payer deducts from a payment and deposits with the government.",
    what: "Some payments to suppliers or service providers are made after deducting TDS. The rules that apply are confirmed by the accountant." },
  "g.tcs": { t: "TCS", full: "Tax collected at source (GST)", ab: ["TCS"],
    short: "Tax an online marketplace collects on its sellers' sales.",
    what: "If Tradex later runs a marketplace where other sellers sell to customers, GST rules may require it to collect TCS on those sales and report it. Treatment is to be defined by the accountant." },
  "g.upi": { t: "UPI", full: "Unified Payments Interface", ab: ["UPI"],
    short: "India's instant bank-to-bank payment method (Google Pay, PhonePe, BHIM…).",
    what: "A common way customers pay online. The payment provider confirms the payment; refunds go back to the same UPI account." },
  "g.utr": { t: "UTR", full: "Unique transaction reference", ab: ["UTR"],
    short: "The bank's reference number for a transfer.",
    what: "Every NEFT/RTGS/IMPS transfer and bank settlement has a UTR. It is used to match money in the bank statement with orders, settlements and refunds.", rel: ["g.reconciliation", "g.neft"] },
  "g.sftp": { t: "SFTP", full: "Secure file transfer", ab: ["SFTP"],
    short: "A secure way for a supplier to drop data files for Tradex.",
    what: "Some suppliers send stock or price files over SFTP instead of an API. Each file is validated before any data is used." },
  "g.uat": { t: "UAT", full: "User acceptance testing", ab: ["UAT"], short: "Testing by business users before something goes live." },
  "g.nist": { t: "NIST 800-88", full: "Media sanitisation standard", ab: ["NIST"],
    short: "The standard used for certified data erasure of storage devices.",
    what: "Describes how to wipe drives so that data cannot be recovered. Tradex records a certificate for each erased device.", rel: ["g.data-erasure"] },
  "g.sop": { t: "SOP", full: "Standard operating procedure", ab: ["SOP"], short: "A written, step-by-step way of doing a task." },
  "g.oem": { t: "OEM", full: "Original equipment manufacturer", ab: ["OEM"], short: "The brand that made the product (for example Dell or Canon)." },
  "g.rpo": { t: "RPO", full: "Recovery point objective", ab: ["RPO"],
    short: "The most data that may be lost if systems must be restored from backup.",
    what: "An RPO of 5 minutes means backups are frequent enough that at most about 5 minutes of changes could be lost." },
  "g.wty": { t: "WTY", full: "Warranty policy code", ab: ["WTY"],
    short: "The code and version of a warranty policy (for example WTY v2026.1).",
    what: "Policies are versioned. Each order line keeps the version that applied at the time of sale, so later policy changes never change an existing customer's terms.", rel: ["g.policy-version", "g.snapshot"] },

  /* ---------------------------------------------------------------- business terms */
  "g.reservation": { t: "Reservation", short: "Stock set aside for an order so no one else can buy it.",
    what: "When an order is placed (or a checkout holds stock for a short time), units are reserved. A reservation lowers ATP straight away; the physical stock drops only when the parcel is dispatched. Reservations that expire or are cancelled release the units.",
    rel: ["g.atp"] },
  "g.safety-buffer": { t: "Safety buffer", short: "A few units held back from sale to cover counting errors or branch sales.",
    what: "A quantity subtracted when calculating ATP, so the website does not promise the very last units.", rel: ["g.atp"] },
  "g.quarantine": { t: "Quarantine", short: "A holding area for stock that cannot be sold yet.",
    what: "Returned parcels, RTO parcels and new deliveries awaiting inspection are placed in quarantine. These units are not available to sell anywhere until an inspector records a result (disposition).",
    why: "It stops faulty, wrong or unchecked items from being sold again by mistake.", rel: ["g.disposition", "g.qc", "g.data-erasure"] },
  "g.disposition": { t: "Disposition", short: "The decision about what happens to a returned or inspected unit.",
    what: "After inspection, operations decides the unit's future: resell at its grade, regrade (for example A → B), repair, return to the supplier, or scrap for parts. This is separate from the refund decision.",
    rel: ["g.quarantine", "g.condition", "g.rtv"] },
  "g.refund": { t: "Refund", short: "Money returned to the customer, decided and paid by finance.",
    what: "A refund moves through: requested → approved → submitted to the payment provider → pending → completed (or failed). Support may request it; finance approves and executes it. Each refund is created once — repeating the approval returns the same refund rather than paying twice.",
    rel: ["g.idempotency", "g.cn"] },
  "g.serial": { t: "Serialised unit · unit ID", short: "One physical item tracked individually by its serial number.",
    what: "Laptops, cameras, GPUs and other high-value items are tracked one by one. Each unit gets a Tradex unit ID (for example U-000781) linked to the maker's serial number, so its history — receipt, inspection, sale, return — is always known.",
    rel: ["g.sku"] },
  "g.condition": { t: "Condition & grade", short: "Whether an item is new, open box, refurbished (Grade A/B) or used.",
    what: "Condition is part of what makes a SKU. Refurbished and used items carry a grade describing their cosmetic state, with an inspection report and photos. The grade shown to customers must match the inspection.",
    rel: ["g.sku", "g.qc"] },
  "g.landed": { t: "Landed cost", short: "What an item really cost to get into stock.",
    what: "Supplier price plus freight, duties and other known costs, excluding GST that can be claimed back. Margin and price floors are calculated from it.", rel: ["g.margin"] },
  "g.margin": { t: "Margin & price floor", short: "Profit left after cost; the floor is the lowest price allowed.",
    what: "Margin = (net selling price ex-GST − landed cost) ÷ net price. A price below the floor, or a discount that takes margin below the minimum, needs an approved override.",
    rel: ["g.landed", "g.override"] },
  "g.override": { t: "Override", short: "A recorded exception to a normal rule, approved by someone with authority.",
    what: "For example selling below the price floor or accepting a return outside the policy window. The approver, reason and time are recorded in the audit log.", rel: ["g.approval", "g.audit"] },
  "g.price-list": { t: "Price list · dealer tier", short: "The set of prices a group of buyers gets.",
    what: "Consumers see the public price list. Approved dealers are placed on a tier (for example Silver, Gold) with its own price list and quantity breaks. The exact order in which lists, quantity tiers and promotions apply is still being confirmed.",
    rel: ["g.b2b", "g.quote", "g.promotion"] },
  "g.quote": { t: "Quote", short: "A price offer to a dealer, valid for a limited time.",
    what: "Staff prepare a quotation for a dealer's request. Once accepted within its validity, the quoted prices are locked for the order.", rel: ["g.price-list", "g.b2b"] },
  "g.promotion": { t: "Promotion · coupon", short: "A time-limited discount, automatic or by code.",
    what: "Promotions have eligibility, dates and stacking rules (which discounts can combine). They are checked against margin floors before going live.", rel: ["g.margin"] },
  "g.credit-limit": { t: "Credit limit · payment terms", short: "How much a dealer may owe and how long they have to pay.",
    what: "Approved dealers may buy on credit (for example 30 days) up to a limit. Orders that would exceed the limit, or accounts with overdue invoices, are held for finance.", rel: ["g.b2b"] },
  "g.debit-note": { t: "Debit note", short: "A document raising an amount owed, for example to a supplier for a shortage.",
    what: "Issued to a supplier when goods were short, damaged or overcharged, reducing what Tradex owes them.", rel: ["g.cn", "g.three-way"] },
  "g.three-way": { t: "Three-way match", short: "Checking the supplier invoice against the PO and the GRN before paying.",
    what: "Quantities and prices on the supplier's invoice must agree with what was ordered (PO) and what was received (GRN). Differences are held for review instead of being paid.",
    rel: ["g.po", "g.grn", "g.debit-note"] },
  "g.idempotency": { t: "Idempotency · duplicate-safe", short: "Doing the same action twice has the effect of doing it once.",
    what: "If a button is clicked twice or a network call is retried, Tradex recognises the repeat and returns the first result — so an order, payment or refund is never created twice.",
    rel: ["g.refund"] },
  "g.reconciliation": { t: "Reconciliation", short: "Comparing records from two systems and resolving any differences.",
    what: "For example: payments captured on the website vs. the payment provider's settlement vs. the bank statement; COD collected vs. courier remittance. Every mismatch becomes an item for finance to resolve.",
    rel: ["g.settlement", "g.utr", "g.exception"] },
  "g.settlement": { t: "Settlement", short: "The payment provider's transfer of collected money to Tradex's bank.",
    what: "The provider pays out in batches, minus its fees. Settlement reports are matched to individual orders and refunds.", rel: ["g.reconciliation"] },
  "g.webhook": { t: "Webhook", short: "An automatic notification one system sends to another when something happens.",
    what: "For example, the payment provider tells Tradex \"payment captured\". Webhooks can arrive late or twice, so Tradex handles repeats safely and checks the provider directly if one is missing.",
    rel: ["g.idempotency"] },
  "g.exception": { t: "Exception · exception queue", short: "A case the system could not finish safely on its own, assigned to a person.",
    what: "When a rule cannot proceed — a payment captured without an order, a courier sync failing, a stock count variance — an exception is created with an owner, a deadline and an escalation path.",
    why: "Routine work runs automatically; people only handle the unusual cases.", rel: ["g.rule-codes", "g.sla"] },
  "g.audit": { t: "Audit log", short: "A permanent record of who did what, when, and why.",
    what: "Approvals, price changes, refunds, stock adjustments, permission changes and views of sensitive data are recorded with the person, time, old and new values and reason. Entries cannot be edited." },
  "g.maker-checker": { t: "Maker–checker", short: "One person prepares an action, a different person approves it.",
    what: "Used for sensitive actions such as payouts, bank-detail changes and large refunds, so no single person can move money alone. Also called separation of duties.", rel: ["g.approval", "g.audit"] },
  "g.approval": { t: "Approval · threshold", short: "A decision needed from someone with authority before an action goes ahead.",
    what: "Actions above a limit (value, discount, quantity) wait for approval by the role named in the authority matrix. The limits shown in the prototype are examples to be set by the client.",
    rel: ["g.maker-checker", "g.delegation"] },
  "g.delegation": { t: "Delegation", short: "Temporarily handing your approvals to a colleague while you are away.",
    what: "A manager can name a stand-in for a period. The stand-in's decisions are recorded as made on the manager's behalf." },
  "g.snapshot": { t: "Order snapshot", short: "The price, policy and warranty terms frozen on each order line at the time of sale.",
    what: "Later changes to prices, return policies or warranty terms never change existing orders. Returns and warranty claims always use the snapshot.",
    rel: ["g.policy-version"] },
  "g.policy-version": { t: "Policy version", short: "A dated version of a returns, warranty or other policy (for example Returns v2026.2).",
    what: "Policies are versioned so that each order is judged by the rules that applied when it was placed.", rel: ["g.snapshot"] },
  "g.reverse-pickup": { t: "Reverse pickup", short: "The courier collects a return from the customer.",
    what: "Booked once a return is authorised. The pickup gets its own AWB; when the parcel reaches Tradex it is scanned into quarantine.", rel: ["g.rma", "g.awb"] },
  "g.eway": { t: "E-way bill · e-invoice", short: "Government documents for moving goods and for invoices, where required.",
    what: "An e-way bill is generated for moving goods above a value limit set by GST rules; an e-invoice registers an invoice with the government portal (IRN). Which ones apply to Tradex is to be confirmed by finance.",
    rel: ["g.irn", "g.gst"] },
  "g.backorder": { t: "Backorder", short: "An order line accepted although the stock is not yet available.",
    what: "Only allowed when the product's policy permits it and the lead time is shown to the buyer. On purchase orders, a backorder is the part a supplier has not yet delivered." },
  "g.partner-stock": { t: "Partner / supplier stock", short: "Stock held by a supplier, not in a Tradex location.",
    what: "Suppliers can share what they have available. It is shown separately (\"ships in 4–6 days · partner stock\") and is never counted as Tradex's own sellable stock until confirmed or received.",
    rel: ["g.freshness", "g.lead-time"] },
  "g.supplier-fulfilment": { t: "Supplier fulfilment (pilot)", short: "The supplier ships an order straight to the customer.",
    what: "A pilot model where Tradex sells and the supplier dispatches. It needs a tracking number and serial capture from the supplier. It is not the default model at launch." },
  "g.freshness": { t: "Feed freshness · stale", short: "How recently a supplier updated its stock or prices.",
    what: "Supplier availability is only trusted for a limited time. When an update is overdue the feed is marked stale and its stock stops being offered until refreshed." },
  "g.lead-time": { t: "Lead time", short: "How long it takes from ordering to having the goods.", what: "Supplier lead time is used in reorder points and in delivery promises for partner stock." },
  "g.fill-rate": { t: "Fill rate", short: "The share of ordered quantity a supplier actually delivered.", what: "Used to compare supplier reliability, together with lead time, defects and response time." },
  "g.pick-pack": { t: "Pick · pack · dispatch", short: "The warehouse steps between an order and the courier.",
    what: "Pick = collect the items from their bins (scanning each serial). Pack = check, pack and label the parcel. Dispatch = hand the parcel to the courier, which reduces physical stock and starts tracking.",
    rel: ["g.manifest", "g.bin", "g.awb"] },
  "g.manifest": { t: "Handover manifest", short: "The list of parcels handed to a courier in one pickup.",
    what: "The courier signs or scans it so both sides agree which parcels left the warehouse." , rel: ["g.pick-pack"] },
  "g.bin": { t: "Bin · location code", short: "An exact storage place inside a warehouse or branch.",
    what: "Codes such as WH-BLR A-14 mean location WH-BLR, aisle/bin A-14. Stock is tracked to the bin so pickers know where to go and counts can be done shelf by shelf." },
  "g.cycle-count": { t: "Cycle count", short: "Counting a few bins regularly instead of closing for a full stock-take.",
    what: "Counted quantities are compared with the system. A difference (variance) locks the bin for picking until it is investigated; adjustments above a threshold need approval.",
    rel: ["g.adjustment", "g.bin"] },
  "g.adjustment": { t: "Stock adjustment", short: "A correction to recorded stock, with a reason and, above a limit, approval.",
    what: "Used for count differences, damage or found stock. Every adjustment is recorded in the audit log with who approved it.", rel: ["g.cycle-count", "g.audit"] },
  "g.transfer": { t: "Stock transfer · in transit", short: "Moving stock between warehouse and branches.",
    what: "When a transfer ships, the units leave the source location and are \"in transit\" (not sellable). They become sellable at the destination only after the receiving scan." },
  "g.data-erasure": { t: "Data erasure certificate", short: "Proof that a storage device was securely wiped.",
    what: "Laptops, drives, phones and other devices with storage are wiped with an approved method before resale, repair or return to a supplier. The certificate is kept against the unit. Customer data is never browsed or copied.",
    rel: ["g.nist", "g.quarantine"] },
  "g.review-flag": { t: "Review flag", short: "A warning that a person should look at a case — not an automatic rejection.",
    what: "Raised by a rule when something looks unusual, for example a serial number that does not match the unit sold. A manager records the decision and the reason; the system never rejects or accuses on its own.",
    rel: ["g.rule-codes"] },
  "g.rule-codes": { t: "Rule & reference codes", short: "Codes like A22, T33 or R19 shown in the prototype for traceability.",
    what: "A-codes (A22, A37, A13.2…) name automation rules listed on the Automation page. T-codes (T17, T33…) point to the blueprint's test scenarios and R-codes (R19…) to requirements from the client meeting. They let reviewers trace a behaviour back to its source.",
    notes: ["Staff do not need to know these codes to use the screens."] },
  "g.phase": { t: "Phase 1A · 1B · P2", short: "When a feature is planned to be delivered.",
    what: "1A = first release; 1B = second part of Phase 1; P2 / P3 = later phases. Turn on \"Phase notes\" in the prototype bar to see the phase of each feature." },
  "g.channel": { t: "Sales channel", short: "Where an order came from: website, branch POS, WhatsApp, staff-assisted or dealer.",
    what: "All channels sell from the same stock and follow the same order, payment and fulfilment steps.", rel: ["g.pos", "g.assisted"] },
  "g.assisted": { t: "Assisted order", short: "An order a staff member places for a customer (phone, WhatsApp, walk-in).",
    what: "Uses the same prices, stock and checks as the website. The customer pays through a payment link or at the branch." },
  "g.submission": { t: "Vendor submission", short: "A product, price or stock update sent by a vendor for Tradex to review.",
    what: "Vendors cannot change the live catalog directly. Their submissions are checked (quality, duplicates, pricing) and approved, sent back for changes, or rejected with a reason." },
  "g.vendor": { t: "Vendor · supplier", short: "A business that supplies Tradex with products.",
    what: "Suppliers sell to Tradex (Tradex buys and resells). A pilot model lets a supplier ship Tradex orders directly. A marketplace, where vendors sell to customers themselves, is a separate later extension.",
    rel: ["g.submission", "g.partner-stock", "g.supplier-fulfilment"] },
  "g.payout": { t: "Payout · statement", short: "Money Tradex pays a vendor, and the statement explaining it.",
    what: "The statement lists invoices, credit/debit notes and deductions for the period, so the vendor can see how the payout was calculated." },
  "g.sync": { t: "Sync · sync lag", short: "Keeping two systems up to date with each other, and how far behind one is.",
    what: "Stock sync lag is how many seconds the website's available stock is behind the stock system. A small lag is normal; a growing lag raises an alert." },
  "g.job-queue": { t: "Background jobs · queue", short: "Work the system does in the background (imports, syncs, messages).",
    what: "Jobs wait in a queue and are retried safely if they fail. A long queue or repeated failures create an exception for someone to look at." },
  "g.consent": { t: "Consent", short: "The customer's recorded permission for marketing messages.",
    what: "Order and service updates are sent as part of the purchase. Marketing by e-mail or WhatsApp needs separate, recorded consent that the customer can withdraw at any time." },

  /* ---------------------------------------------------------------- terms added with the page help (2026-09-28) */
  "g.abc-class": { t: "A / B / C class",
    short: "Grouping items by value and risk to decide how often they are counted.",
    what: "A-class items (high value or fast-moving) are counted most often and C-class least. The frequencies shown on screens (weekly, monthly, quarterly) are sample values.",
    rel: ["g.cycle-count"] },
  "g.ai": { t: "AI",
    full: "Artificial intelligence",
    ab: ["AI"],
    short: "Software that makes judgement-based suggestions, such as answering questions.",
    what: "Not used in Phase 1: all automation is fixed, deterministic rules. Judgement-based assistants are planned for a later phase only." },
  "g.allocation": { t: "Allocation",
    short: "The exact stock set aside for an order line so the warehouse can pick it.",
    what: "When the payment is confirmed, the order's temporary reservation becomes an allocation: a quantity at one location and, for serialised items, one specific unit (for example U-000812). For serial-specific items (refurbished, open box) the unit is fixed when the order is placed, because the customer bought that unit's photos and inspection report; for new stock a valid serial can be allocated when it is picked. A serial can never be allocated to two active orders, and if a bin turns out to be empty the difference is investigated with a stock count.",
    rel: ["g.reservation","g.serial","g.pick-pack"] },
  "g.allow-list": { t: "Allow-list (image domains)",
    short: "The only web addresses Tradex will download images from.",
    what: "Image links in imports and in the product editor are fetched only from approved supplier or manufacturer domains over HTTPS. Anything else — private network addresses, the server itself, cloud metadata addresses — is refused.",
    why: "An import file can never make Tradex reach its own internal systems, and images only come from sources whose usage rights are agreed." },
  "g.alt-text": { t: "Alt text",
    short: "A short written description of an image.",
    what: "Read aloud by screen readers for people who cannot see the image, and shown if the image fails to load. It says what the picture shows — for example “Dell Latitude 5420 laptop, front view, lid open”." },
  "g.amc": { t: "AMC",
    full: "Annual maintenance contract",
    ab: ["AMC"],
    short: "A yearly service contract to maintain a customer's equipment." },
  "g.aov": { t: "AOV",
    full: "Average order value",
    ab: ["AOV"],
    short: "Net sales divided by the number of orders.",
    what: "What an average order is worth in the period. It changes when customers buy more items per order, or more expensive ones." },
  "g.attribute": { t: "Attribute · category template",
    short: "A typed field a category asks for, such as RAM (number, in GB) or Ports (list).",
    what: "Every product shares the same core fields (title, brand, model…). Each category adds its own attributes through a template: a label, a data type, a unit, the allowed values, whether it is required, and whether it is used as a filter or in search. Templates are versioned.",
    why: "Structured attributes make filters, comparisons and search work, and let a new ordinary category be added by configuration instead of development." },
  "g.auto-accept": { t: "Auto-accept (availability)",
    short: "A routine stock update accepted without a manual check because it stays within agreed limits.",
    what: "Tradex can accept routine availability refreshes from a trusted vendor automatically when they stay within validated limits. Bigger or unusual changes are held for a check, and the old value stays live until then. The limits, and when automatic acceptance is switched on, are to be confirmed by Tradex.",
    rel: ["g.freshness","g.partner-stock"] },
  "g.aws": { t: "AWS",
    full: "Amazon Web Services",
    ab: ["AWS"],
    short: "The cloud hosting used by Tradex's existing system.",
    what: "Hosting may stay on AWS if access, account ownership, cost and fit are sound; being on AWS does not by itself make the existing system suitable." },
  "g.blind-count": { t: "Blind count",
    short: "Counting without seeing how many the system expects.",
    what: "The counter records what is physically in the bin without seeing the expected quantity, so the count is not influenced by it.",
    rel: ["g.cycle-count"] },
  "g.ca": { t: "CA",
    full: "Chartered accountant",
    ab: ["CA"],
    short: "Tradex's qualified external accountant.",
    what: "Approves the accounting export format and the ledger mapping, and may receive scheduled accounting exports through an expiring link protected by a one-time password.",
    rel: ["g.voucher","g.control-totals"] },
  "g.canonical-state": { t: "Canonical delivery state",
    see: "g.canonical-status" },
  "g.canonical-status": { t: "Canonical status (courier)",
    short: "Tradex's own standard shipment status that each courier's codes are translated into.",
    what: "Couriers report progress in their own codes (for example PU, IT, OFD, UD). Tradex maps every code to one short list of statuses — Dispatched, In transit, Out for delivery, Delivered, Delivery failed, Returned to origin — and keeps the courier's original message unchanged as evidence.",
    why: "Staff and customers see the same statuses whichever courier is used, and the courier's raw message is still there if there is a dispute.",
    notes: ["A courier update never changes unrelated records such as the payment or the invoice."],
    rel: ["g.awb","g.rto","g.pod"] },
  "g.capture": { t: "Authorised · captured",
    short: "Authorised = the bank approved and blocked the amount; captured = the money was actually taken.",
    what: "A payment attempt can be created, pending, authorised, captured, failed or expired. Only captured payments are paid out to Tradex, later, in a settlement. Tradex treats an order as paid only when the payment provider confirms the capture — through a signed message (webhook) or a direct status check — never because the customer's browser showed a success page.",
    rel: ["g.webhook","g.settlement","g.reconciliation","g.payment-attempt"] },
  "g.challan": { t: "Delivery challan",
    short: "The document that travels with goods from the supplier, listing what is in the delivery.",
    what: "Receiving staff check the delivery against the challan and the purchase order. Its number is recorded on the goods receipt (GRN) together with the supplier's invoice number.",
    rel: ["g.grn","g.asn"] },
  "g.chargeback": { t: "Chargeback",
    short: "A payment reversed by the customer's bank after the customer disputed it.",
    what: "The provider takes the disputed amount back from Tradex's settlement. Tradex can contest it by sending evidence (invoice, proof of delivery) before the provider's deadline; the provider or bank decides the outcome.",
    rel: ["g.settlement","g.reconciliation"] },
  "g.checkout-link": { t: "Secure checkout link",
    short: "A link the customer opens to confirm the address and final price, and pay.",
    what: "Sent by WhatsApp, SMS or e-mail for WhatsApp and staff-assisted orders. The same price checks, stock reservation and payment rules apply as on the website. In the prototype the link expires together with its stock reservation.",
    rel: ["g.draft-basket","g.reservation"] },
  "g.click-to-chat": { t: "Click-to-chat",
    short: "A WhatsApp button on the website that opens a chat carrying a product reference.",
    what: "The chat starts with a reference to the product the customer was viewing. It is only a reference — not a trusted price and not an order. A staff member or the guided flow then confirms the item and creates a draft basket.",
    rel: ["g.draft-basket"] },
  "g.control-totals": { t: "Control totals",
    short: "Counts and sums compared between two systems to prove nothing was lost, duplicated or changed.",
    what: "For example the number of documents, taxable value, tax and receipts in an accounting export from Tradex, compared with what the accounting system acknowledged or the accountant imported. Any difference points to documents that are missing or failed, and is investigated.",
    rel: ["g.reconciliation"] },
  "g.cut-off": { t: "Courier cut-off",
    short: "The latest time a parcel must be packed and booked to leave with today's pickup.",
    what: "Orders packed after the cut-off go with the next pickup. Times shown on screens (for example 14:00 express, 16:30 courier cut-off, 17:00 pickup) are sample values set by the business and the courier.",
    rel: ["g.sla"] },
  "g.discrepancy": { t: "Discrepancy · discrepancy case",
    short: "A recorded mismatch between what was expected and what was found — investigated, never ignored.",
    what: "Found while receiving a supplier delivery (short, extra or wrong items, substitutions, damage, duplicate serial numbers) or when a transfer or stock count does not match. The affected units are held — never sellable until someone decides — and a discrepancy case with an owner and a due date is closed by receiving the item, correcting the record, or an approved loss.",
    rel: ["g.grn","g.transfer","g.substitution","g.exception"] },
  "g.dlt": { t: "DLT registration",
    full: "Business SMS registration (India)",
    ab: ["DLT"],
    short: "The registration of a business's SMS sender identity and message templates in India.",
    what: "Business SMS in India are sent under a registration on the telecom operators' DLT (distributed ledger) platform, which lists the sender and its approved message templates. The exact requirements are confirmed with the SMS provider." },
  "g.dpdp": { t: "DPDP",
    full: "Digital Personal Data Protection (India)",
    ab: ["DPDP"],
    short: "India's personal-data protection law and its rules.",
    what: "It governs how personal data may be collected, used, kept and deleted, and how people's requests about their data are handled. Which provisions apply to Tradex, and from when, is for qualified review — the screens treat it as an implementation checklist, not a legal determination.",
    rel: ["g.consent","g.masking"] },
  "g.draft-basket": { t: "Draft basket",
    short: "Items agreed in a chat, saved in the order system before the customer confirms and pays.",
    what: "A staff member (or, from release 1B, the guided WhatsApp flow) selects the exact product, condition and quantity and saves them as a draft basket (for example DB-0417) with live prices and stock. It is not an order yet: prices mentioned in the chat are not trusted and are recalculated by the pricing engine. It becomes an order only when the customer confirms the address and final price and pays through a secure checkout link.",
    rel: ["g.checkout-link","g.assisted","g.channel"] },
  "g.email-auth": { t: "SPF · DKIM · DMARC",
    full: "Email sender authentication",
    ab: ["SPF","DKIM","DMARC"],
    short: "Settings that let receiving mail servers check an email really comes from Tradex.",
    what: "When all three pass, Tradex's order emails are less likely to land in spam and harder for others to fake." },
  "g.faq": { t: "FAQ · approved answer",
    full: "Frequently asked questions",
    ab: ["FAQ","FAQs"],
    short: "A versioned, approved answer to a common question.",
    what: "Approved answers are used word for word by the guided bot, by agents as quick replies and on the help centre. Every change is a new version that must be approved before it goes live." },
  "g.for": { t: "FOR",
    full: "Free on road · freight terms",
    ab: ["FOR"],
    short: "The supplier delivers to the named place and pays the transport.",
    what: "A common Indian trade term on purchase orders. \"FOR destination\" means the supplier bears the freight up to Tradex's delivery location. When Tradex pays freight instead, it is added to the goods' landed cost.",
    notes: ["The exact responsibilities follow the terms agreed on each PO."],
    rel: ["g.landed"] },
  "g.formula-safe": { t: "Formula-injection safe",
    short: "Exported text that a spreadsheet could run as a formula is made harmless.",
    what: "If a text cell starts with =, +, −, @, a tab or a line break, spreadsheet programs may treat it as a formula — which can be misused (for example a customer name typed as =HYPERLINK(…)). Tradex puts an apostrophe (') in front of such text so it is shown, never run.",
    rel: ["g.csv"] },
  "g.gateway-fee": { t: "Gateway fee",
    short: "The payment provider's charge for processing a payment, plus GST on it.",
    what: "The provider deducts its fee (and GST on the fee) before paying out, so the bank receives less than was captured. The fee is checked against the agreed rates and recorded in the accounts as gateway charges. Actual rates depend on the provider agreement.",
    rel: ["g.settlement"] },
  "g.gstr8": { t: "GSTR-8",
    full: "GST return of an e-commerce operator",
    ab: ["GSTR-8"],
    short: "The GST return in which an e-commerce operator reports tax it collected at source (TCS).",
    what: "Only relevant if Tradex later runs a marketplace for other sellers. Whether and how it applies is for the accountant to confirm before marketplace activation.",
    rel: ["g.tcs"] },
  "g.handoff": { t: "Handoff (bot → person)",
    short: "The bot passes the conversation to a person, with the full history and the reason.",
    what: "The guided bot hands over whenever the customer asks for a person or when it cannot answer safely — for example an ambiguous product, a failed verification, or a sensitive topic such as a payment dispute or an unsafe product. The agent sees everything the bot already did." },
  "g.hash-chain": { t: "Hash chain · tamper-evident log",
    short: "Each log entry stores a fingerprint of the previous one, so changes to history can be detected.",
    what: "A hash is a short fingerprint calculated from an entry's contents. Because every audit entry includes the previous entry's hash, editing or deleting an old entry breaks the chain, which raises a security alert.",
    rel: ["g.audit"] },
  "g.ho": { t: "HO",
    full: "Head office",
    ab: ["HO"],
    short: "The company's head office.",
    what: "Used for things kept centrally, such as the official accounting books." },
  "g.hosted-checkout": { t: "Hosted checkout · card data",
    short: "The payment page run by the payment provider, so Tradex never sees or stores card details.",
    what: "Customers enter card or bank details on the provider's own secure page. Tradex receives only the result and a reference. Any saved card is held by the provider as a token (whether saved cards are offered is to be confirmed).",
    rel: ["g.payment-attempt"] },
  "g.http": { t: "HTTP status",
    full: "Web request result code",
    ab: ["HTTP"],
    short: "The numeric reply a web service gives to a request, such as 504 or 429.",
    what: "Shown in job evidence. 504 means the provider's system did not answer in time (gateway timeout); 429 means too many requests were sent in a short time (rate limit). Both are usually temporary, so the job is retried." },
  "g.inr": { t: "INR",
    full: "Indian rupee",
    ab: ["INR"],
    short: "India's currency (₹)." },
  "g.invoice-series": { t: "Invoice series",
    short: "A numbered sequence of invoices, for example TX/26-27/004873.",
    what: "Each series has a prefix (by channel, branch, dealer invoices or credit notes) and restarts each financial year. Numbers are given only when an invoice is finalised; cancelled numbers are kept as cancelled and never reused, so the sequence has no unexplained gaps.",
    rel: ["g.gst","g.fy"] },
  "g.ip": { t: "IP address",
    full: "Internet Protocol address",
    ab: ["IP"],
    short: "The network address a device connects from.",
    what: "Shown in the audit log and sign-in history to help spot unusual access. An IP allow-list limits access to approved addresses." },
  "g.ist": { t: "IST",
    full: "Indian Standard Time",
    ab: ["IST"],
    short: "India's time zone (UTC+05:30)." },
  "g.kill-switch": { t: "Kill switch",
    short: "A switch that stops an automation rule immediately.",
    what: "Turning it off stops new runs at once; runs in progress finish, and waiting work moves to a person's manual queue. Nothing already done is undone, and nothing is replayed automatically when the rule is switched back on.",
    rel: ["g.exception"] },
  "g.kpi": { t: "KPI",
    full: "Key performance indicator",
    ab: ["KPI","KPIs"],
    short: "A number used to judge how well something is working.",
    what: "For example an automation rule's success rate, exception rate or hours saved, or the figures in the owner's daily digest." },
  "g.lakh-crore": { t: "L · Cr (lakh · crore)",
    short: "Indian number units: 1 lakh (L) = 1,00,000 and 1 crore (Cr) = 100 lakh = 1,00,00,000.",
    what: "Amounts are shown in the Indian number system. ₹6.2 L = ₹6,20,000. ₹1.84 Cr = ₹1,84,00,000 (18.4 million). Digits are grouped the Indian way: 1,86,420 = 186,420." },
  "g.ledger": { t: "Stock ledger · movement",
    short: "The permanent list of every stock change; each line is a movement.",
    what: "Every receipt, inspection result, reservation, dispatch, return, transfer and adjustment is recorded as a movement with its type, document and person. Movements are never edited or deleted — a mistake is corrected with a reversing movement — so the ledger always adds up to the current balances.",
    rel: ["g.adjustment","g.audit"] },
  "g.llm": { t: "LLM",
    full: "Large language model",
    ab: ["LLM"],
    short: "AI that writes free-text answers — not used in Phase 1.",
    what: "Phase 1 uses a guided bot that follows fixed menus and approved answers only. Free-text AI answers are a later-phase option that needs accuracy, handoff, privacy and cost controls first.",
    rel: ["g.phase","g.ai"] },
  "g.llp": { t: "LLP",
    full: "Limited liability partnership",
    ab: ["LLP"],
    short: "A form of registered business: a partnership whose partners have limited liability.",
    what: "One of the business types (the \"constitution\") an applicant declares, alongside proprietorship, partnership and private limited company. It is compared with the GST registration during verification.",
    rel: ["g.gstin"] },
  "g.lr": { t: "LR",
    full: "Lorry receipt",
    ab: ["LR"],
    short: "The transporter's receipt and tracking number for goods sent by road.",
    what: "Issued by a road transport company when it takes a consignment. Like a courier's AWB, its number is used to track the shipment and to match it when it arrives.",
    rel: ["g.awb","g.asn"] },
  "g.masking": { t: "Masked data · reveal",
    short: "Personal details shown partly hidden (pr•••@…) until someone with permission reveals them.",
    what: "Email addresses, phone numbers and similar details are masked by default. Staff who need the full value click Reveal and give a reason; it is shown for a short time and the reveal is recorded in the audit log. Which fields are masked for which roles, and how long a reveal lasts, is still to be confirmed.",
    rel: ["g.audit"] },
  "g.mis-slot": { t: "Mis-slotted unit",
    short: "A unit stored in the wrong bin.",
    what: "Found when a scan does not match what the bin should hold. The unit is put back where it belongs and both bins are recounted; stock records are never changed silently.",
    rel: ["g.bin","g.cycle-count"] },
  "g.msg-template": { t: "Message template",
    short: "A pre-approved, versioned message format — for example order_confirmed v3 or checkout_link v2.",
    what: "Order updates, checkout links and reminders are sent from templates so that the wording is consistent and approved. WhatsApp requires approved templates for messages the business starts outside the service window.",
    rel: ["g.service-window","g.consent"] },
  "g.mtd": { t: "MTD · QTD",
    full: "Month to date · quarter to date",
    ab: ["MTD","QTD"],
    short: "From the first day of the current month (or quarter) up to today.",
    what: "Period shortcuts used in reports. MTD covers the current month so far; QTD covers the current quarter so far." },
  "g.net-sales": { t: "Gross & net sales",
    short: "Gross = invoiced sales before returns; net = gross minus returns and refunds (credit notes).",
    what: "<b>Gross sales</b> is the tax-invoice line value after line discounts, before returns. <b>Net sales</b> is gross minus the credit notes (returns and refunds) issued in the period. Unless a label says otherwise, both exclude GST; shipping recovery and payment fees are not included.",
    notes: ["A refund can fall in a later period than the sale. It reduces net sales in the period its credit note is issued.","These are the definitions shown on the Reports page of this prototype; the final wording is agreed with Finance."],
    rel: ["g.cn","g.gst"] },
  "g.ocr": { t: "OCR",
    full: "Optical character recognition",
    ab: ["OCR"],
    short: "Reading text from a scanned document or photo automatically.",
    what: "Reading supplier invoices by OCR is a later-phase candidate (A31); a person would still review tax, totals and unclear lines." },
  "g.payment-attempt": { t: "Payment attempt",
    short: "One try by a customer to pay for an order.",
    what: "Each time a customer starts paying — by card, UPI, netbanking, EMI or COD — a payment attempt is created. If it fails, the next try is a new attempt, so one order can have several. Attempts have their own states (created, pending, authorised, captured, failed, expired), separate from the order's state.",
    rel: ["g.capture"] },
  "g.pending-change": { t: "Pending change · live version",
    see: "g.pending-version" },
  "g.pending-version": { t: "Live and pending versions",
    short: "A change to a live product waits as a new version while the last approved version stays on sale.",
    what: "Editing a published product — by Tradex staff or by a vendor — creates a new pending version (for example v7) while the last approved version (v6) stays live. Customers only see the live version. When the change is approved and published it replaces the old one; if it is rejected or withdrawn, the live version simply continues. The version history keeps every earlier version. Only a safety or stock concern takes a listing off sale immediately.",
    why: "Changes can be prepared and reviewed without taking a product off sale, and nobody can change what customers see without a review.",
    rel: ["g.submission","g.sensitive-edit","g.snapshot"] },
  "g.penny-drop": { t: "Penny-drop check",
    short: "Verifying a bank account with a tiny test payment and checking the account holder's name.",
    what: "A small amount (for example ₹1) is sent to the account. The bank's reply confirms the account exists and returns the holder's name, which is compared with the business's legal name (often shown as a match percentage) before the account can be used for payouts or refunds. The exact verification method is still to be confirmed.",
    rel: ["g.ifsc","g.kyc","g.maker-checker"] },
  "g.pin": { t: "PIN code",
    full: "Postal Index Number",
    ab: ["PIN"],
    short: "India's 6-digit postal code.",
    what: "Used to check whether and how fast a courier can deliver to an address and whether cash on delivery is allowed there, and to work out shipping and the place of supply (and, where a location price list exists, which prices apply).",
    rel: ["g.serviceability","g.place-of-supply"] },
  "g.place-of-supply": { t: "Place of supply",
    short: "The state where a sale counts as made for GST.",
    what: "It decides how GST is split: in the same state as the Tradex business selling → CGST + SGST; in another state → IGST. For a delivery it normally follows where the goods are delivered. The number in brackets is the GST state code (for example 29 = Karnataka) — the same two digits that start a GSTIN. The exact rules are applied as confirmed by finance.",
    rel: ["g.gst-parts","g.gstin"] },
  "g.pod": { t: "POD",
    full: "Proof of delivery",
    ab: ["POD"],
    short: "The courier's confirmation that a parcel was delivered.",
    what: "Usually a recipient's signature, a delivery OTP or a photo, recorded by the courier and received with the tracking update.",
    rel: ["g.awb","g.canonical-state"] },
  "g.polling": { t: "Polling · status check",
    short: "Tradex asking the payment provider directly for a payment's status.",
    what: "If the provider's message (webhook) about a payment does not arrive in time, Tradex asks the provider's system for the status instead. This recovers payments whose message was lost, so no paid order is left waiting.",
    rel: ["g.webhook"] },
  "g.privileged": { t: "Privileged role",
    short: "A role that can change permissions, money settings or integrations.",
    what: "Privileged accounts (on screen: Owner, Operations admin, Finance) must use two-step sign-in, and sensitive changes they make need a second approver. Which roles are privileged is still to be confirmed.",
    rel: ["g.mfa","g.maker-checker"] },
  "g.qty-tier": { t: "Quantity tier · bulk price",
    short: "A lower unit price for buying more of the same product (for example 5+ or 10+ units).",
    what: "Dealer price lists can include quantity tiers, also called quantity breaks. With <b>all-units</b> pricing, every unit gets the price of the tier the quantity reaches. With <b>graduated</b> pricing, only the units inside each band get that band's price. Which method Tradex uses, and whether quantities are counted per product or across a mixed basket, is to be confirmed by the business.",
    rel: ["g.price-list","g.margin"] },
  "g.quote-lock": { t: "Quote lock",
    short: "A calculated price held for a limited time so the buyer can order at that price.",
    what: "After the engine calculates a price it can lock it as a quote version with an expiry time (samples on this page: 30 minutes on the website, 24 hours for staff-assisted quotes). When the order reserves stock the price and quantity tier are checked again; if something material changed, the buyer must confirm. The real validity times are to be confirmed by the business.",
    rel: ["g.quote","g.reservation"] },
  "g.record-scope": { t: "Record scope",
    short: "Which records a user may see — for example only their own branch.",
    what: "Besides what a role may do, each user can be limited to certain records: a branch manager sees only their branch's orders, stock and sales. Reports, exports and scheduled deliveries all apply the same scope, so a file never contains more than the person may see.",
    rel: ["g.audit"] },
  "g.recovery-time": { t: "Recovery time objective",
    full: "RTO — the longest acceptable time to restore service",
    short: "How quickly the system must be working again after a major failure.",
    what: "The blueprint proposes 4 hours or less for the agreed major recovery scenario, proven by a timed restore rehearsal. (Not the courier \"RTO\", which means return to origin.)",
    rel: ["g.rpo"] },
  "g.redirect": { t: "Redirect (301)",
    short: "An old web address that automatically sends visitors on to the current page.",
    what: "When a product's address changes, or a product is archived, the old address keeps working: visitors and search engines are sent to the current page or a useful replacement. “301” is the web code for a permanent move.",
    rel: ["g.slug","g.seo"] },
  "g.remittance": { t: "Remittance (COD)",
    short: "A courier's payment to Tradex of the cash it collected on delivery.",
    what: "Couriers collect COD cash from customers and pay it to Tradex in batches, some days later, with a file listing the orders. Each batch is matched to the delivered COD orders; short or late batches are chased.",
    rel: ["g.cod","g.reconciliation"] },
  "g.rubric": { t: "Grading rubric",
    short: "Tradex's written criteria for each refurbished grade.",
    what: "The rubric says what Grade A and Grade B mean for each product type — cosmetic marks, screen, battery health, keyboard, function tests. Units are graded against it: by vendors for the stock they supply, and by Tradex at inspection. It is versioned (for example rubric v2.1); the criteria shown in the prototype are samples.",
    rel: ["g.condition","g.qc"] },
  "g.rule-set": { t: "Pricing rule set · version",
    short: "The versioned set of pricing rules the price engine uses (for example v2026.09.3).",
    what: "It contains the order of the calculation steps, the stacking policy and the checks. A new version is released only after approval, and each order line stores the rule-set version that priced it, so any price can be explained later.",
    rel: ["g.snapshot","g.policy-version"] },
  "g.safety-stock": { t: "Safety stock",
    short: "Extra units kept on hand to cover sales spikes or late deliveries while waiting for a new order.",
    what: "Part of the reorder point: reorder point = average sales per day × lead time + safety stock. The quantity is set by the business. It is different from the <i>safety buffer</i>, which is held back from ATP so the website does not promise the very last units.",
    rel: ["g.rop","g.safety-buffer","g.lead-time"] },
  "g.sellable": { t: "Sellable on-hand",
    short: "Units on the shelf that are fit to sell, including those already reserved.",
    what: "Physical stock at a Tradex location in a sellable state. It already excludes quarantine, damaged, repair and in-transit units, so those are never subtracted a second time when ATP is calculated.",
    rel: ["g.atp","g.quarantine","g.reservation"] },
  "g.seller-of-record": { t: "Seller of record",
    short: "The business that legally sells to the customer and issues the invoice.",
    what: "In Tradex's launch model Tradex is always the seller of record, even when a supplier ships the order. In a future marketplace an external seller could be the seller of record — which is why that model needs separate agreements, settlement and tax decisions.",
    rel: ["g.vendor","g.supplier-fulfilment"] },
  "g.sensitive-edit": { t: "Sensitive edit",
    short: "A change to a product that always needs Tradex review before it applies.",
    what: "Changes to brand, condition, warranty, tax classification or payout account, and extraordinary price changes, are always reviewed by Tradex — even for an approved product from a trusted vendor. Routine stock refreshes are not sensitive edits. Where an “extraordinary” price change starts is to be confirmed by Tradex.",
    rel: ["g.pending-version","g.submission"] },
  "g.seo": { t: "SEO",
    full: "Search engine optimisation",
    ab: ["SEO"],
    short: "Making product pages easy for search engines such as Google to find and show well.",
    what: "Meaningful page titles and descriptions, stable web addresses, redirects when an address changes, and accurate product information for search engines. No setting can guarantee a search ranking.",
    rel: ["g.slug","g.redirect"] },
  "g.service-window": { t: "WhatsApp service window",
    short: "The period after a customer's last WhatsApp message when the business may reply freely (24 hours today).",
    what: "Inside the window Tradex can send normal replies. Once it closes, only pre-approved message templates may be sent until the customer writes again. WhatsApp's current documentation describes the window as 24 hours, restarted by each customer message.",
    rel: ["g.wa-template","g.msg-template","g.consent","g.bsp"] },
  "g.serviceability": { t: "Serviceability",
    short: "Whether a courier can deliver to a PIN code — for this parcel's size and value, how fast, and whether cash on delivery is possible there.",
    what: "Checked at checkout before the customer pays (it sets the delivery promise and whether COD is offered) and again when the courier is booked. If the main courier cannot serve an address, the parcel is booked manually with another carrier or delivered by own staff. The coverage rules are still to be confirmed.",
    rel: ["g.pin","g.cod","g.awb"] },
  "g.settlement-cycle": { t: "T+2 · T+3",
    full: "Settlement timing",
    ab: ["T+2","T+3"],
    short: "How many days after the payment day (T) the money is paid out.",
    what: "T+2 means the provider pays out two days after the payment day. Some methods (for example EMI) can settle later than others, so a payment missing from today's settlement is not necessarily lost. The actual cycles depend on the provider agreement.",
    rel: ["g.settlement"] },
  "g.short-pick": { t: "Short pick",
    short: "The picker could not find the expected quantity in the bin.",
    what: "The line cannot be completed from that bin. It is recorded, a count of the bin is opened, and the order moves to exceptions so someone finds stock elsewhere (for example by a transfer from a branch) or gives the customer a choice.",
    rel: ["g.cycle-count","g.transfer","g.exception"] },
  "g.slug": { t: "URL slug",
    short: "The readable last part of a product's web address.",
    what: "In tradex.in/p/dell-latitude-5420-…, the part after /p/ is the slug. It uses lower-case words and hyphens so people and search engines can read it. When a slug changes, the old address is redirected to the new one.",
    rel: ["g.redirect","g.seo"] },
  "g.sod": { t: "Separation of duties (SoD)",
    short: "Keeping the two halves of a risky task with different people.",
    what: "For example, the person who requests a discount cannot approve it, and user administration is kept apart from warehouse work. Where a small team cannot separate duties, the combination is reviewed afterwards.",
    rel: ["g.maker-checker"] },
  "g.ssrf": { t: "SSRF",
    full: "Server-side request forgery",
    ab: ["SSRF"],
    short: "An attack that tricks a server into calling addresses it should not.",
    what: "Imports that fetch files from supplier addresses only call addresses on an approved list, as the blueprint's security requirements ask." },
  "g.stacking": { t: "Stacking policy",
    short: "The written rules for which discounts may be combined on one order.",
    what: "For example: at most one coupon per order, and consumer promotions never on top of dealer prices. When two promotions that cannot combine both qualify, the rule with the higher priority wins — the system does not automatically pick the larger discount.",
    rel: ["g.promotion","g.rule-set"] },
  "g.staging": { t: "Staging (imports)",
    short: "A holding area where imported rows wait until they are checked and approved.",
    what: "Uploaded files and supplier feeds land in staging first. Rows are validated and matched there. Nothing in staging is visible to customers or changes stock; only valid, approved changes are published to the catalog.",
    rel: ["g.csv","g.pending-version"] },
  "g.staging-env": { t: "Staging · production",
    short: "Staging is the separate test copy of the system; production is the live system.",
    what: "New rules, changes and releases are tried on staging first, with masked copies of real data, before they reach production. The two use separate accounts and credentials." },
  "g.state-machine": { t: "State machine · guard",
    short: "A fixed list of statuses a record can have, and the allowed moves between them.",
    what: "Orders, payments, fulfilment, refunds and returns each have their own list of statuses and rules for moving from one to the next. A <b>guard</b> is the condition that must be true before a move is allowed — for example, an order becomes Confirmed only when the payment is captured and the stock is allocated. Moves that are not allowed are refused, so a late or repeated message can never push a record backwards.",
    why: "Keeping separate state machines (order, payment, fulfilment, refund, return) instead of one status field lets each part of the work move on its own and stay truthful.",
    rel: ["g.idempotency","g.webhook"] },
  "g.stock-ageing": { t: "Stock ageing · receipt cohort",
    short: "How long units have been in stock since they were received.",
    what: "Stock is grouped by when it was received (its receipt cohort). Old stock ties up money and can lose value, so it is a candidate for a price change, a transfer to another site, or clearance.",
    notes: ["Age limits shown on screens (for example \"older than 90 days\") are examples."] },
  "g.substitution": { t: "Substitution",
    short: "A different item, unit, configuration or condition in place of the one ordered — never accepted silently.",
    what: "From a supplier: the units are held until the buyer approves the substitution (and the PO is amended) or rejects it and returns the goods. When shipping to a customer: it needs the customer's agreement and a manager's approval recorded on the order; otherwise the line is treated as a short pick.",
    rel: ["g.discrepancy","g.po","g.allocation","g.approval"] },
  "g.tbc": { t: "TBC",
    full: "To be confirmed",
    ab: ["TBC"],
    short: "A placeholder the client still has to confirm.",
    what: "Values marked TBC (limits, targets, retention periods…) are shown for discussion only and are not enforced as approved rules." },
  "g.tls": { t: "TLS certificate",
    full: "Transport Layer Security",
    ab: ["TLS"],
    short: "The website's security certificate that encrypts connections (the padlock in the browser).",
    what: "It must be renewed before it expires, or browsers warn visitors. An alert fires when expiry is close." },
  "g.tolerance": { t: "Match tolerance",
    short: "How far a supplier invoice may differ from the PO before the bill is held.",
    what: "In the three-way match, small price differences within the tolerance are accepted; anything beyond it is held for finance or the buyer. In the prototype the sample tolerance is ±2% or ₹500 per line, quantity must match exactly and tax must match — the real values are set by finance.",
    rel: ["g.three-way"] },
  "g.variance": { t: "Variance (count difference)",
    short: "The difference between the counted and the expected quantity.",
    what: "Counted minus expected. A negative variance means units are missing; a positive one means more were found. A variance changes stock only after it is approved and posted as an adjustment.",
    rel: ["g.cycle-count","g.adjustment"] },
  "g.volumetric": { t: "Volumetric weight",
    short: "A weight worked out from the parcel's size, used by couriers for charging.",
    what: "Couriers usually charge by the actual weight or the volumetric weight, whichever is higher. Volumetric weight is calculated from length × width × height with the courier's own formula." },
  "g.voucher": { t: "Voucher · ledger",
    short: "Accounting terms: a voucher is one entry in the books; a ledger is an account it is posted to.",
    what: "When Tradex exports an invoice, receipt or credit note, the accounting system records it as a voucher and posts it to ledgers (for example the customer's account, sales, GST, bank). If a ledger does not exist in the accounting system, the export fails until it is created.",
    rel: ["g.control-totals"] },
  "g.vpa": { t: "VPA · UPI ID",
    full: "Virtual payment address",
    ab: ["VPA"],
    short: "A UPI ID such as name@bank, used to send and receive UPI payments.",
    what: "UPI refunds go back to the customer's UPI ID. If that ID has been closed, the refund fails and must be sent to a new, verified UPI ID or to a bank account.",
    rel: ["g.upi"] },
  "g.wa-template": { t: "Message template (WhatsApp)",
    short: "A pre-approved message format, required for business-started WhatsApp messages and for replies outside the service window.",
    what: "Templates have a category (utility, authentication or marketing), placeholders such as {{1}}, and a version. Meta approves them through the WhatsApp provider before use. Marketing templates need the customer's opt-in.",
    notes: ["Charges depend on the category and the service window; budgets must use a dated written quote."],
    rel: ["g.service-window","g.bsp","g.consent"] },
  "g.wave": { t: "Pick wave",
    short: "A batch of released orders picked together in one route through the warehouse.",
    what: "Orders are grouped so a picker walks the shelves once, in bin order, collecting items for several orders. In the prototype a wave starts when at least 3 released orders are waiting or at the express cut-off — sample triggers to be set by the business.",
    notes: ["Whether waves are stored as permanent records is still to be confirmed."],
    rel: ["g.pick-pack","g.bin"] },
  "g.wismo": { t: "WISMO",
    full: "\"Where is my order?\"",
    ab: ["WISMO"],
    short: "Customer questions asking where their order is.",
    what: "Used to measure the courier tracking sync: fewer such questions means customers can see their delivery status themselves." },
});
